495	// ProposalView 是当前轮次本地提议的只读视图。
496	type ProposalView struct {
497		Round   uint64
498		BlockID string
499		TxIDs   []string
500		// Empty 表示本轮是否为空块提议（无交易）。
501		Empty bool
502	}
