194	// 确认后序号不大于已确认序号被拒；缺口交易可入池等待，查询指出最早缺口。
195	func TestGapAndConfirmedSequence(t *testing.T) {
196		keys := genKeys(t, 4)
197		n, _ := newTestNode(t, keys, 10)
198	
199		tx2 := NewTransaction(keys[0].priv, 2, []byte("two"), 1, 100)
200		if _, err := n.Submit(tx2); err != nil {
201			t.Fatal(err)
202		}
203		acct := n.Account(keys[0].pub)
204		if acct.Gap != 1 || len(acct.Pending) != 1 {
205			t.Fatalf("gap = %d pending = %d, want gap 1", acct.Gap, len(acct.Pending))
206		}
207		if acct.Pending[0].Note != "waiting-pack" {
208			t.Fatalf("note = %q, want waiting-pack", acct.Pending[0].Note)
209		}
210	
211		tx1 := NewTransaction(keys[0].priv, 1, []byte("one"), 1, 100)
212		if _, err := n.Submit(tx1); err != nil {
213			t.Fatal(err)
214		}
215		acct = n.Account(keys[0].pub)
216		if acct.Gap != 0 {
217			t.Fatalf("gap = %d, want 0", acct.Gap)
218		}
219	
220		p, err := n.Propose()
221		if err != nil {
222			t.Fatal(err)
223		}
224		if len(p.TxIDs) != 2 || p.TxIDs[0] != tx1.ID() || p.TxIDs[1] != tx2.ID() {
225			t.Fatalf("block order wrong: %v", p.TxIDs)
226		}
227		confirmByVotes(t, n, keys, p.BlockID)
228		if n.CurrentRound() != 2 {
229			t.Fatalf("round = %d, want 2", n.CurrentRound())
230		}
231	
232		acct = n.Account(keys[0].pub)
233		if acct.ConfirmedSequence != 2 {
234			t.Fatalf("confirmed = %d, want 2", acct.ConfirmedSequence)
235		}
236		// 序号不大于已确认序号
237		replay := NewTransaction(keys[0].priv, 2, []byte("two"), 1, 100)
238		if _, err := n.Submit(replay); reason(err) != ReasonDuplicate {
239			t.Fatalf("same tx replay got %v, want duplicate", err)
240		}
241		oldSeq := NewTransaction(keys[0].priv, 1, []byte("one"), 9, 100)
242		if _, err := n.Submit(oldSeq); reason(err) != ReasonOldSequence {
243			t.Fatalf("got %v, want %s", err, ReasonOldSequence)
244		}
245	}
