534					decisions = append(decisions, "reject:"+reason(err))
535					return
536				}
537				decisions = append(decisions, "accept:"+res.TxID+":"+res.EvictedID+":"+res.ReplacedID)
538			}
539			for r := 1; r <= 3; r++ {
