	if _, err := n.EndRound(); err != nil { // 轮次 2
		t.Fatal(err)
	}
	if _, err := n.EndRound(); err != nil { // 轮次 3
		t.Fatal(err)
	}
	info, _ := n.Tx(a.ID())
	if info.Status != StatusDropped || info.DropReason != DropReasonPoolCapacity || info.DropRound != 1 {
		t.Fatalf("dropped tx must not become expired: %+v", info)
	}
}

